import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshStandardNodeMaterial,
  DoubleSide,
} from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {any} [textContent]
 * @property {any} [intent]
 * @property {any} [cinematicPrimitives]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} fontAtlas
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} emit
 * @property {any} primitives
 * @property {any} tier
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------
  // Helpers
  // -----------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const disposables = [];

  const setOpacity = (value) => {
    group.traverse((obj) => {
      if (obj.isMesh) {
        const mat = obj.material;
        mat.transparent = true;
        mat.opacity = value;
        mat.needsUpdate = true;
      }
    });
  };

  // -----------------------------------------------------------------
  // Root group
  // -----------------------------------------------------------------
  const group = new Group();

  // -----------------------------------------------------------------
  // Backdrop plane with vertical gradient
  // -----------------------------------------------------------------
  const bgGeom = new PlaneGeometry(6.8, 2.0);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    side: DoubleSide,
  });
  bgMat.colorNode = mix(
    color('#121218'),
    color('#0b0b10'),
    uv().y
  );
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, 0);
  group.add(bgMesh);
  disposables.push({ geometry: bgGeom, material: bgMat });

  // -----------------------------------------------------------------
  // Top hairline rule
  // -----------------------------------------------------------------
  const hairTopGeom = new PlaneGeometry(6.8, 0.006);
  const hairTopMat = new MeshStandardNodeMaterial({
    color: '#23232b',
    roughness: 0.8,
    metalness: 0.1,
    side: DoubleSide,
  });
  const hairTopMesh = new Mesh(hairTopGeom, hairTopMat);
  hairTopMesh.position.set(0, 1.0 - 0.003, 0.01);
  group.add(hairTopMesh);
  disposables.push({ geometry: hairTopGeom, material: hairTopMat });

  // -----------------------------------------------------------------
  // Wordmark (left block)
  // -----------------------------------------------------------------
  const wordmarkItem = items.find((it) => it.text === 'NOVA ATELIER') || { text: 'NOVA ATELIER' };
  const wordmark = ctx.fontAtlas.createText(wordmarkItem.text, {
    fontSize: 34,
    color: '#16161d',
    align: 'left',
  });
  wordmark.position.set(-2.4, 0.6, 0.02);
  group.add(wordmark);

  // -----------------------------------------------------------------
  // Accent bar beneath wordmark
  // -----------------------------------------------------------------
  const accentGeom = new PlaneGeometry(0.3, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.0,
    side: DoubleSide,
  });
  const accentMesh = new Mesh(accentGeom, accentMat);
  accentMesh.position.set(-2.4, 0.45, 0.01);
  group.add(accentMesh);
  disposables.push({ geometry: accentGeom, material: accentMat });

  // -----------------------------------------------------------------
  // Columns definitions
  // -----------------------------------------------------------------
  const columnDefs = [
    {
      xCenter: -0.425,
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      xCenter: 1.15,
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      xCenter: 2.725,
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const lineHeight = 0.2; // approximate scene‑unit step per line

  columnDefs.forEach((col, colIdx) => {
    // Header
    const header = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#16161d',
      align: 'center',
    });
    header.position.set(col.xCenter, 0.2, 0.02);
    group.add(header);

    // Links
    col.links.forEach((linkText, i) => {
      const link = ctx.fontAtlas.createText(linkText, {
        fontSize: 13,
        color: '#16161d',
        align: 'center',
      });
      link.position.set(col.xCenter, 0.2 - (i + 1) * lineHeight, 0.02);
      group.add(link);
    });
  });

  // -----------------------------------------------------------------
  // Legal line (full width)
  // -----------------------------------------------------------------
  const legalItem = items.find((it) => it.role === 'legal') || {
    text: '(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.',
  };
  const legalText = ctx.fontAtlas.createText(legalItem.text, {
    fontSize: 9,
    color: '#16161d',
    align: 'center',
  });
  legalText.position.set(0, -0.625, 0.02);
  group.add(legalText);

  // -----------------------------------------------------------------
  // Bottom hairline rule (above legal line)
  // -----------------------------------------------------------------
  const hairBottomGeom = new PlaneGeometry(6.8, 0.006);
  const hairBottomMat = new MeshStandardNodeMaterial({
    color: '#23232b',
    roughness: 0.8,
    metalness: 0.1,
    side: DoubleSide,
  });
  const hairBottomMesh = new Mesh(hairBottomGeom, hairBottomMat);
  // Positioned 0.25 units above legal line, centered on that line
  hairBottomMesh.position.set(0, -0.372, 0.01);
  group.add(hairBottomMesh);
  disposables.push({ geometry: hairBottomGeom, material: hairBottomMat });

  // -----------------------------------------------------------------
  // Fade‑up entrance animation
  // -----------------------------------------------------------------
  const entrance = gsap.timeline({ paused: true });
  group.position.y += 0.2;
  setOpacity(0);
  entrance
    .to(
      { opacity: 0 },
      {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: function () {
          setOpacity(this.targets()[0].opacity);
        },
      }
    )
    .to(group.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
  entrance.play();

  // -----------------------------------------------------------------
  // Cleanup
  // -----------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    entrance.kill();
    disposables.forEach((d) => {
      if (d.geometry) d.geometry.dispose();
      if (d.material) d.material.dispose();
    });
    // dispose any fonts/text objects that have dispose method
    group.traverse((obj) => {
      if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
      if (obj.material && obj.material.dispose) obj.material.dispose();
    });
  };

  return group;
}
